private int version() { return repository.findRace(RACE).orElseThrow().version(); }

private void createLoopRace() {
    raceService.createRace(new CreateRaceRequest(RACE, "LOOP", 2, "req-create"));
}

private void register(String bib) {
    raceService.registerRunner(RACE, new RegisterRunnerRequest(bib, null, version(), "req-reg-" + bib));
}

private LapPassResponse submit(String bib, int lap, String point, long elapsed) {
    String id = "lp-" + bib + "-" + lap + point;
    ServiceResult result = raceService.submitLap(RACE, bib,
        new SubmitLapRequest(id, lap, point, elapsed, "timer-1", version(), "req-" + id));
    assertThat(result.status()).isEqualTo(201);
    return (LapPassResponse) result.body();
}

private void submitFullLaps(String bib) {
    submit(bib, 1, "A", 40_000);
    submit(bib, 1, "B", 50_000);
    submit(bib, 1, "FINISH", 60_000);
    submit(bib, 2, "A", 70_000);
    submit(bib, 2, "B", 80_000);
    submit(bib, 2, "FINISH", 120_000);
}
```

Wait: requestIds must be unique per request (else idempotency replay kicks in with different params → 409). Using "req-" + id is unique per lap point. For penalty: "req-pen". For seal: "req-seal".

